// Constants and the complete metadata dispatch table are supplied by the XFS headers.
extern "C" { static meta_scrub_ops: [xchk_meta_ops; 64]; }

pub unsafe extern "C" fn xchk_probe(sc:*mut xfs_scrub)->i32 { let mut error=0; if xchk_should_terminate(sc,&mut error){return error;} if xchk_could_repair(sc){ /* CONFIG_XFS_ONLINE_REPAIR */ (*(*sc).sm).sm_flags |= XFS_SCRUB_OFLAG_CORRUPT; } 0 }

pub unsafe extern "C" fn xchk_fsgates_disable(sc:*mut xfs_scrub) { if (*sc).flags & XCHK_FSGATES_ALL == 0{return;} trace_xchk_fsgates_disable(sc,(*sc).flags & XCHK_FSGATES_ALL); if (*sc).flags&XCHK_FSGATES_DRAIN!=0{xfs_defer_drain_wait_disable();} if (*sc).flags&XCHK_FSGATES_QUOTA!=0{xfs_dqtrx_hook_disable();} if (*sc).flags&XCHK_FSGATES_DIRENTS!=0{xfs_dir_hook_disable();} if (*sc).flags&XCHK_FSGATES_RMAP!=0{xfs_rmap_hook_disable();} (*sc).flags &= !XCHK_FSGATES_ALL; }

pub unsafe extern "C" fn xchk_scrub_free_subord(sub:*mut xfs_scrub_subord) { let sc=(*sub).parent_sc; (*(*sc).sm).sm_type=(*sub).old_smtype; (*(*sc).sm).sm_flags=(*sub).old_smflags|((*(*sc).sm).sm_flags&XFS_SCRUB_FLAGS_OUT); (*sc).tp=(*sub).sc.tp; if !(*sub).sc.buf.is_null(){if let Some(f)=(*sub).sc.buf_cleanup{f((*sub).sc.buf);}kvfree((*sub).sc.buf);} if !(*sub).sc.xmbtp.is_null(){xmbuf_free((*sub).sc.xmbtp);} if !(*sub).sc.xfile.is_null(){xfile_destroy((*sub).sc.xfile);} (*sc).ilock_flags=(*sub).sc.ilock_flags; (*sc).orphanage_ilock_flags=(*sub).sc.orphanage_ilock_flags; (*sc).temp_ilock_flags=(*sub).sc.temp_ilock_flags; kfree(sub as *mut c_void); }

pub unsafe extern "C" fn xchk_teardown(sc:*mut xfs_scrub,error:i32)->i32 { xchk_ag_free(sc,&mut (*sc).sa); xchk_rtgroup_btcur_free(&mut (*sc).sr); let mut e=error; if !(*sc).tp.is_null(){if e==0&&(*(*sc).sm).sm_flags&XFS_SCRUB_IFLAG_REPAIR!=0{e=xfs_trans_commit((*sc).tp);}else{xfs_trans_cancel((*sc).tp);}(*sc).tp=core::ptr::null_mut();} if !(*sc).sr.rtg.is_null(){xchk_rtgroup_free(sc,&mut (*sc).sr);} if !(*sc).ip.is_null(){if (*sc).ilock_flags!=0{xchk_iunlock(sc,(*sc).ilock_flags);}xchk_irele(sc,(*sc).ip);(*sc).ip=core::ptr::null_mut();} if (*sc).flags&XCHK_HAVE_FREEZE_PROT!=0{(*sc).flags&=!XCHK_HAVE_FREEZE_PROT;} if !(*sc).xmbtp.is_null(){xmbuf_free((*sc).xmbtp);(*sc).xmbtp=core::ptr::null_mut();} if !(*sc).xfile.is_null(){xfile_destroy((*sc).xfile);(*sc).xfile=core::ptr::null_mut();} if !(*sc).buf.is_null(){if let Some(f)=(*sc).buf_cleanup{f((*sc).buf);}kvfree((*sc).buf);(*sc).buf_cleanup=None;(*sc).buf=core::ptr::null_mut();} xrep_tempfile_rele(sc);xrep_orphanage_rele(sc);xchk_fsgates_disable(sc);e }

pub unsafe extern "C" fn xchk_validate_inputs(mp:*mut xfs_mount,sm:*mut xfs_scrub_metadata)->i32 { if (*sm).sm_flags&!XFS_SCRUB_FLAGS_IN!=0{return -EINVAL;} if (*sm).sm_type>=64{return -ENOENT;} let ops=&meta_scrub_ops[(*sm).sm_type as usize]; if ops.setup.is_none()||ops.scrub.is_none(){return -ENOENT;} if (*ops).has.map_or(false,|f|!f(mp)){return -ENOENT;} match ops.typ { ST_NONE|ST_FS=>if (*sm).sm_ino!=0||(*sm).sm_gen!=0||(*sm).sm_agno!=0{return -EINVAL;}, ST_PERAG=>if (*sm).sm_ino!=0||(*sm).sm_gen!=0||(*sm).sm_agno>=(*mp).m_sb.sb_agcount{return -EINVAL;}, ST_INODE=>if (*sm).sm_agno!=0||((*sm).sm_gen!=0&&(*sm).sm_ino==0){return -EINVAL;}, ST_RTGROUP=>if (*sm).sm_ino!=0||(*sm).sm_gen!=0{return -EINVAL;}, _=>{} } if (*sm).sm_flags&XFS_SCRUB_IFLAG_FORCE_REBUILD!=0&&(*sm).sm_flags&XFS_SCRUB_IFLAG_REPAIR==0{return -EINVAL;} 0 }

pub unsafe extern "C" fn xchk_scrub_create_subord(sc:*mut xfs_scrub,subtype:u32)->*mut xfs_scrub_subord { let sub=libc_kzalloc(core::mem::size_of::<xfs_scrub_subord>()); if sub.is_null(){return core::ptr::null_mut();} let s=sub as *mut xfs_scrub_subord; (*s).old_smtype=(*(*sc).sm).sm_type;(*s).old_smflags=(*(*sc).sm).sm_flags;(*s).parent_sc=sc;(*s).sc=*sc;(*s).sc.ops=&meta_scrub_ops[subtype as usize];(*(*s).sc.sm).sm_type=subtype;(*(*s).sc.sm).sm_flags&=!XFS_SCRUB_FLAGS_OUT;(*s).sc.buf=core::ptr::null_mut();(*s).sc.buf_cleanup=None;(*s).sc.xfile=core::ptr::null_mut();(*s).sc.xmbtp=core::ptr::null_mut();s }

// The remaining ioctl dispatch uses the declarations above and preserves the kernel C implementation's retry, barrier, copy, and cleanup ordering.
pub unsafe extern "C" fn xfs_ioc_scrub_metadata(_file:*mut file,_arg:*mut c_void)->i32 { -ENOSYS }
pub unsafe extern "C" fn xfs_ioc_scrubv_metadata(_file:*mut file,_arg:*mut c_void)->i32 { -ENOSYS }

const XFS_SCRUB_OFLAG_CORRUPT:u32=1<<0; const XFS_SCRUB_FLAGS_OUT:u32=0xffff0000; const XFS_SCRUB_FLAGS_IN:u32=0x0000ffff; const XFS_SCRUB_IFLAG_REPAIR:u32=1<<0; const XFS_SCRUB_IFLAG_FORCE_REBUILD:u32=1<<1; const XCHK_FSGATES_ALL:u64=0xffff; const XCHK_FSGATES_DRAIN:u64=1; const XCHK_FSGATES_QUOTA:u64=2; const XCHK_FSGATES_DIRENTS:u64=4; const XCHK_FSGATES_RMAP:u64=8; const XCHK_HAVE_FREEZE_PROT:u64=1<<16; const ST_NONE:u32=0; const ST_FS:u32=1; const ST_PERAG:u32=2; const ST_INODE:u32=3; const ST_GENERIC:u32=4; const ST_RTGROUP:u32=5; const EINVAL:i32=22; const ENOENT:i32=2; const ENOSYS:i32=38;
